from dataclasses import dataclass


@dataclass
class Num:
    v: int


@dataclass
class Add:
    l: 'Expr'
    r: 'Expr'


@dataclass
class Mul:
    l: 'Expr'
    r: 'Expr'


Expr = Num | Add | Mul


def eval_expr(e: Expr) -> int:
    """Evaluate an expression tree: Num is its value, Add sums and Mul multiplies its children."""
    match e:
        case Num(v):
            return v
        case Add(l, r):
            return eval_expr(l) + eval_expr(r)
        case Mul(l, r):
            return eval_expr(l) * eval_expr(r)


def test_num() -> None:
    assert eval_expr(Num(5)) == 5
    assert eval_expr(Num(0)) == 0
    assert eval_expr(Num(-3)) == -3


def test_add() -> None:
    assert eval_expr(Add(Num(2), Num(3))) == 5


def test_mul() -> None:
    assert eval_expr(Mul(Num(4), Num(3))) == 12


def test_nested() -> None:
    # (2 + 3) * (4 + 1) = 25
    e = Mul(Add(Num(2), Num(3)), Add(Num(4), Num(1)))
    assert eval_expr(e) == 25
    # 2 + 3 * 4 = 14
    assert eval_expr(Add(Num(2), Mul(Num(3), Num(4)))) == 14


def test_identities_and_zero() -> None:
    assert eval_expr(Mul(Num(0), Add(Num(7), Num(8)))) == 0
    assert eval_expr(Add(Num(0), Num(9))) == 9
    assert eval_expr(Mul(Num(1), Num(9))) == 9


def test_negative_values() -> None:
    assert eval_expr(Add(Num(-2), Num(-3))) == -5
    assert eval_expr(Mul(Num(-2), Num(3))) == -6
    assert eval_expr(Mul(Num(-2), Num(-3))) == 6


def test_deep_left_chain() -> None:
    e: Expr = Num(0)
    for i in range(1, 101):
        e = Add(e, Num(i))
    assert eval_expr(e) == 5050


def test_deep_right_chain() -> None:
    e: Expr = Num(1)
    for _ in range(10):
        e = Mul(Num(2), e)
    assert eval_expr(e) == 1024


def test_large_ints() -> None:
    big = 10**20
    assert eval_expr(Mul(Num(big), Num(big))) == 10**40

